cat > $TMPDIR/Scratch.java <<'EOF'
import java.util.Calendar;
import java.util.TimeZone;
public class Scratch {
    public static void main(String[] args) {
        TimeZone gmt = TimeZone.getTimeZone("GMT");
        Calendar start = Calendar.getInstance(gmt);
        start.clear();
        start.set(2020, Calendar.JANUARY, 15, 0, 0, 0);
        Calendar end = Calendar.getInstance(gmt);
        end.clear();
        end.set(2020, Calendar.MARCH, 10, 0, 0, 0);
        System.out.println("start=" + start.getTime() + " end=" + end.getTime());
        System.out.println(org.apache.commons.lang3.time.DurationFormatUtils.formatPeriod(start.getTimeInMillis(), end.getTimeInMillis(), "M'M'd'D'", true, gmt));
    }
}
EOF
javac -cp target/classes -d $TMPDIR $TMPDIR/Scratch.java && java -cp "target/classes:$TMPDIR" Scratch
